// raccoonLogins holds the in-flight browser sign-ins. The state is the key: it
// is generated by start, echoed by the official page and compared on the way
// back, which is what binds a code to *this* attempt.
type raccoonLogins struct {
	mu        sync.Mutex
	m         map[string]*raccoonLogin
	accountMu sync.Mutex
}

type raccoonLogin struct {
	mode       string
	created    time.Time
	claimed    bool
	committing bool
	cancel     context.CancelFunc
	uid        string
	nickname   string
	err        string
}

// raccoonLoginTTL bounds one sign-in attempt. Codes expire upstream quickly, so
// a stale entry is only useful as a clear "start over" answer.
const raccoonLoginTTL = 10 * time.Minute

var (
	errRaccoonLoginExpired = errors.New("登录请求已过期，请重新发起网页登录")
	errRaccoonLoginUsed    = errors.New("登录请求已经处理，请重新发起网页登录")
	errRaccoonLoginMode    = errors.New("请回到面板粘贴桌面登录回调")
	errRaccoonUIDConflict  = errors.New("相同 UID 已属于其他渠道的账号")
	errRaccoonAccountMoved = errors.New("小浣熊账号已被其他操作更新或删除，请重试")
	errRaccoonAccountSave  = errors.New("小浣熊账号保存失败，请检查账号存储并重试")
)

func (l *raccoonLogins) put(state, mode string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.m == nil {
		l.m = map[string]*raccoonLogin{}
	}
	now := time.Now()
	for k := range l.m {
		l.lookupLocked(k, now)
	}
	l.m[state] = &raccoonLogin{mode: mode, created: now}
}

func (l *raccoonLogins) lookupLocked(state string, now time.Time) *raccoonLogin {
	entry := l.m[state]
	if entry != nil && !entry.committing && now.Sub(entry.created) >= raccoonLoginTTL {
		if entry.cancel != nil {
			entry.cancel()
		}
		delete(l.m, state)
		return nil
	}
	return entry
}

func (l *raccoonLogins) get(state string) (raccoonLogin, bool) {
	l.mu.Lock()
	defer l.mu.Unlock()
	entry := l.lookupLocked(state, time.Now())
	if entry == nil {
		return raccoonLogin{}, false
	}
	return *entry, true
}

func (l *raccoonLogins) claim(state string, webOnly bool, cancel context.CancelFunc) error {
	l.mu.Lock()
	defer l.mu.Unlock()
	entry := l.lookupLocked(state, time.Now())
	if entry == nil {
		return errRaccoonLoginExpired
	}
	if webOnly && entry.mode != raccoon.ModeWeb {
		return errRaccoonLoginMode
	}
	if entry.claimed {
		return errRaccoonLoginUsed
	}
	entry.claimed = true
	entry.cancel = cancel
	return nil
}

func (l *raccoonLogins) beginCommit(state string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	entry := l.lookupLocked(state, time.Now())
	if entry == nil {
		return false
	}
	entry.committing = true
	return true
}

func (l *raccoonLogins) finish(state string, rec *accounts.Record, failure string) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if entry, ok := l.m[state]; ok {
		entry.cancel = nil
		entry.committing = false
		entry.err = failure
		if rec != nil {
			entry.uid, entry.nickname = rec.UID, rec.Nickname
		}
	}
}

func (l *raccoonLogins) stop(state string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	entry := l.lookupLocked(state, time.Now())
	if entry == nil || entry.committing || entry.uid != "" {
		return false
	}
	if entry.cancel != nil {
		entry.cancel()
	}
	delete(l.m, state)
	return true
}

// raccoonLoginStart opens one sign-in attempt.
//
// The mode is decided by the panel address, not by a setting: the official page
// only accepts an http loopback redirect with an explicit port, so anything
// else must use the desktop scheme (and the operator then pastes the callback).
func (o *Operations) raccoonLoginStart(w http.ResponseWriter, r *http.Request) {
	var in struct {
		Name string `json:"name"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	host, port, err := net.SplitHostPort(r.Host)
	if err != nil {
		host, port = r.Host, ""
	}
	mode := raccoon.ModeDesktop
	redirect := ""
	if raccoon.IsLoopbackHTTP(scheme, host, port) {
		mode = raccoon.ModeWeb
		redirect = scheme + "://" + r.Host + "/api/v2/raccoon/login/callback"
	}
	state := raccoon.LoginState()
	o.raccoonLogins.put(state, mode)
	callback := raccoon.CallbackURL() // desktop scheme, for reference
	if mode == raccoon.ModeWeb {
		callback = redirect
	}
	out := map[string]any{
		"state":    state,
		"mode":     mode,
		"authUrl":  raccoon.AuthorizeURL(state, mode, redirect),
		"callback": callback,
	}
	if mode == raccoon.ModeWeb {
		out["hint"] = "在打开的页面里完成登录，浏览器会带着授权码回到 " + redirect +
			"；回不到（例如面板在服务器上）就把地址栏整条链接或授权码粘到下面。"
	} else {
		out["hint"] = "登录成功后浏览器会跳到 office-raccoon://… 地址（服务器部署时这一跳打不开属正常）；" +
			"把地址栏整条链接或授权码粘到下面即可。想自动回填，请用 http://localhost:<端口> 打开面板。"
	}
	writeJSON(w, http.StatusOK, out)
}

// raccoonLoginCallback is the web-mode landing page: the official page appends
// the authorization code to this URL.
func (o *Operations) raccoonLoginCallback(w http.ResponseWriter, r *http.Request) {
	state := strings.TrimSpace(r.URL.Query().Get("state"))
	code := firstNonEmpty(strings.TrimSpace(r.URL.Query().Get("authorization_code")),
		strings.TrimSpace(r.URL.Query().Get("code")))
	if code == "" {
		writeRaccoonPage(w, http.StatusBadRequest, "登录未完成", "回调里没有授权码，请回到面板重新发起登录。")
		return
	}
	rec, err := o.completeRaccoonLogin(r.Context(), state, code, "", true)
	if err != nil {
		writeRaccoonPage(w, raccoonLoginHTTPStatus(err), "登录失败", err.Error())
		return
	}
	writeRaccoonPage(w, http.StatusOK, "登录成功",
		"小浣熊账号 "+rec.Nickname+" 已加入账号池，可以关闭这个页面回到面板。")
}

// raccoonLoginComplete finishes an attempt from a pasted callback URL (desktop
// mode) or a bare code.
func (o *Operations) raccoonLoginComplete(w http.ResponseWriter, r *http.Request) {
	var in struct {
		State string `json:"state"`
		URL   string `json:"url"`
		Code  string `json:"code"`
		Name  string `json:"name"`
	}
	if !decode(w, r, &in) {
		return
	}
	state := strings.TrimSpace(in.State)
	code := strings.TrimSpace(in.Code)
	if raw := strings.TrimSpace(in.URL); raw != "" {
		// Accept the whole callback URL, an http callback that failed to load,
		// or the bare code: an operator on a server deployment often has only
		// the address bar (or just the code) to copy.
		parsed, err := raccoon.CodeFromInput(raw, state)
		if err != nil {
			writeErr(w, http.StatusBadRequest, err.Error())
			return
		}
		code = parsed
	}
	if code == "" {
		writeErr(w, http.StatusBadRequest, "缺少授权码")
		return
	}
	rec, err := o.completeRaccoonLogin(r.Context(), state, code, in.Name, false)
	if err != nil {
		writeErr(w, raccoonLoginHTTPStatus(err), err.Error())
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"ok": true, "uid": rec.UID, "nickname": rec.Nickname,
	})
}

// raccoonLoginPoll reports the state of one attempt.
func (o *Operations) raccoonLoginPoll(w http.ResponseWriter, r *http.Request) {
	state := strings.TrimSpace(r.URL.Query().Get("state"))
	entry, ok := o.raccoonLogins.get(state)
	switch {
	case !ok:
		writeJSON(w, http.StatusOK, map[string]any{"status": "expired"})
	case entry.err != "":
		writeJSON(w, http.StatusOK, map[string]any{"status": "error", "message": entry.err})
	case entry.uid != "":
		writeJSON(w, http.StatusOK, map[string]any{
			"status": "ok", "uid": entry.uid, "nickname": entry.nickname,
		})
	default:
		writeJSON(w, http.StatusOK, map[string]any{"status": "pending"})
	}
}

func (o *Operations) raccoonLoginCancel(w http.ResponseWriter, r *http.Request) {
	var in struct {
		State string `json:"state"`
	}
	if !decode(w, r, &in) {
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "cancelled": o.raccoonLogins.stop(strings.TrimSpace(in.State))})
}

func raccoonLoginHTTPStatus(err error) int {
	switch {
	case errors.Is(err, errRaccoonAccountSave):
		return http.StatusInternalServerError
	case errors.Is(err, errRaccoonUIDConflict), errors.Is(err, errRaccoonLoginUsed), errors.Is(err, errRaccoonAccountMoved):
		return http.StatusConflict
	default:
		return http.StatusBadRequest
	}
}

// completeRaccoonLogin exchanges a code, stores the account and kicks the two
// follow-up jobs (catalogue discovery and the sign-up grants) in the background.
func (o *Operations) completeRaccoonLogin(ctx context.Context, state, code, name string, webOnly bool) (*accounts.Record, error) {
	callCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 40*time.Second)
	defer cancel()
	if err := o.raccoonLogins.claim(state, webOnly, cancel); err != nil {
		return nil, err
	}
	cred, err := raccoon.New(nil).ExchangeCode(callCtx, code)
	if err != nil {
		o.raccoonLogins.finish(state, nil, err.Error())
		return nil, err
	}
	if !o.raccoonLogins.beginCommit(state) {
		return nil, errRaccoonLoginExpired
	}
	rec, err := o.saveRaccoonCredential(cred, name, "raccoon-oauth")
	if err != nil {
		o.raccoonLogins.finish(state, nil, err.Error())
		return nil, err
	}
	o.raccoonLogins.finish(state, rec, "")
	o.afterRaccoonLogin(rec)
	return rec, nil
}

func (o *Operations) saveRaccoonCredential(cred raccoon.Credential, name, source string) (*accounts.Record, error) {
	rec := o.raccoonRecord(cred, name)
	if filename, ok := rec.FileName(); cred.UserID == "" || cred.UserID == "unknown" || !ok || filename != rec.UID+".json" {
		return nil, errors.New("小浣熊凭据缺少有效的账号 ID")
	}
	rec.Source = source
	o.raccoonLogins.accountMu.Lock()
	defer o.raccoonLogins.accountMu.Unlock()
	var previous *accounts.Record
	if acc := o.Pool.Get(rec.UID); acc != nil {
		previous = acc.Record()
		if !realm.IsRaccoon(acc.Realm) || previous == nil || !realm.IsRaccoon(previous.Realm) {
			return nil, errRaccoonUIDConflict
		}
		next := previous.WithRaccoonAuth(accounts.RaccoonAuth{})
		if strings.TrimSpace(name) != "" || next.Nickname == "" {
			next.Nickname = rec.Nickname
		}
		next.AccessToken, next.RefreshToken, next.ExpiresAt, next.Source = rec.AccessToken, rec.RefreshToken, rec.ExpiresAt, rec.Source
		profile := rec.RaccoonFields()
		if cred.OrgCode == "" {
			delete(profile, "officeIdentity")
		}
		credentialKeys := []string{"token", "accessToken", "access_token", "refreshToken", "refresh_token"}
		next = next.WithRaccoonFields(func(fields map[string]any) {
			for _, key := range credentialKeys {
				delete(fields, key)
			}
			if cred.OrgCode != "" {
				for _, key := range []string{"officeIdentity", "office_identity", "officeOrgName", "office_org_name", "officeOrgRole", "office_org_role"} {
					delete(fields, key)
				}
			}
			maps.Copy(fields, profile)
		})
		for _, key := range credentialKeys {
			delete(next.Extra, key)
		}
		rec = next
	}
	if o.Persist != nil {
		if err := o.Persist(rec); err != nil {
			if errors.Is(err, accounts.ErrConflict) || errors.Is(err, accounts.ErrDeleted) {
				return nil, errRaccoonAccountMoved
			}
			return nil, errRaccoonAccountSave
		}
	}
	acc := o.Pool.Get(rec.UID)
	if acc == nil {
		if previous != nil {
			return nil, errRaccoonAccountMoved
		}
		o.Pool.Add(rec)
		return rec, nil
	}
	if live := acc.Record(); live != previous {
		if live.RaccoonCredentialVersion() != rec.RaccoonCredentialVersion() || live.RaccoonNeedsLogin() {
			return nil, errRaccoonAccountMoved
		}
		acc.MarkTokenBad(false)
		return live, nil
	}
	updated, ok := o.Pool.UpdateIf(rec.UID, func(current *accounts.Record) bool {
		if o.Pool.Get(rec.UID) != acc || acc.Record() != previous {
			return false
		}
		*current = *rec
		return true
	})
	if !ok {
		return nil, errRaccoonAccountMoved
	}
	return updated, nil
}

// afterRaccoonLogin refreshes the catalogue and probes the sign-up grants. Both
// are best effort: a failure is logged by the service and retried on the next
// scan / manual run.
func (o *Operations) afterRaccoonLogin(rec *accounts.Record) {
	if rec == nil || o.Raccoon == nil {
		return
	}
	acc := o.Pool.Get(rec.UID)
	if acc == nil || !acc.Enabled() {
		return
	}
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
		defer cancel()
		log := o.Raccoon.Log
		if log == nil {
			log = slog.Default()
		}
		if res := o.Raccoon.Discover(ctx, acc); res.Err != nil {
			log.Warn("raccoon discovery after login failed", "err", res.Err)
		}
		if _, err := o.Raccoon.Claim(ctx, acc); err != nil &&
			!errors.Is(err, raccoon.ErrNoSignupTasks) {
			log.Warn("raccoon sign-up claim failed", "err", err)
		}
		// One balance read so the panel shows points without a second click.
		if _, err := o.Raccoon.Credits(ctx, acc); err != nil {
			log.Warn("raccoon credit read after login failed", "err", err)
		}
	}()
}

// raccoonRecord turns a credential into an account record.
func (o *Operations) raccoonRecord(cred raccoon.Credential, name string) *accounts.Record {
	nickname := strings.TrimSpace(name)
	if nickname == "" {
		nickname = "小浣熊 · " + cred.UserID
	}
	extra := map[string]any{
		"userId":         cred.UserID,
		"officeIdentity": firstNonEmpty(cred.OrgCode, "personal"),
		"iam":            cred.IAM,
	}
	if cred.OrgName != "" {
		extra["officeOrgName"] = cred.OrgName
	}
	if cred.OrgRole != "" {
		extra["officeOrgRole"] = cred.OrgRole
	}
	var expiry int64
	if !cred.ExpiresAt.IsZero() {
		expiry = cred.ExpiresAt.Unix()
	}
	return &accounts.Record{
		UID:          "rc-" + cred.UserID,
		Nickname:     nickname,
		Realm:        realm.Raccoon,
		Platform:     "raccoon",
		AccessToken:  cred.Token,
		RefreshToken: cred.RefreshToken,
		ExpiresAt:    expiry,
		AddedAt:      float64(time.Now().Unix()),
		Source:       "raccoon-oauth",
		Enabled:      true,
		// Non-nil slices: the panel and the exporter both treat these as arrays.
		DisabledModels: []string{},
		Extra:          map[string]any{raccoon.ExtraKey: extra},
	}
}

// raccoonModelsRefresh re-runs discovery for one account or the whole channel.
func (o *Operations) raccoonModelsRefresh(w http.ResponseWriter, r *http.Request) {
	var in struct {
		UID string `json:"uid"`
	}
	if r.ContentLength != 0 && !decode(w, r, &in) {
		return
	}
	if o.Raccoon == nil {
		writeErr(w, http.StatusNotImplemented, "raccoon channel is not enabled")
		return
	}
	ctx, cancel := context.WithTimeout(context.WithoutCancel(r.Context()), 2*time.Minute)
	defer cancel()
	targets := o.raccoonAccounts(in.UID)
	if len(targets) == 0 {
		writeErr(w, http.StatusNotFound, "no raccoon account matched")
		return
	}
	results := make([]map[string]any, 0, len(targets))
	for _, acc := range targets {
		res := o.Raccoon.Discover(ctx, acc)
		row := map[string]any{"uid": acc.UID, "models": res.Models, "kept": res.Kept}
		if res.Err != nil {
			row["error"] = res.Err.Error()
		}
		results = append(results, row)
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true, "accounts": results})
}

func (o *Operations) raccoonAccounts(uid string) []*pool.Account {
	uid = strings.TrimSpace(uid)
	var out []*pool.Account
	if uid != "" {
		if acc := o.Pool.Get(uid); acc != nil && realm.IsRaccoon(acc.Realm) {
			out = append(out, acc)
		}
		return out
	}
	for _, acc := range o.Pool.All() {
		if acc != nil && realm.IsRaccoon(acc.Realm) {
			out = append(out, acc)
		}
	}
	return out
}

type raccoonImportInput struct {
	Token            string `json:"token"`
	AccessToken      string `json:"accessToken"`
	LegacyAccess     string `json:"access_token"`
	RefreshToken     string `json:"refreshToken"`
	LegacyRefresh    string `json:"refresh_token"`
	Name             string `json:"name"`
	OfficeIdentity   string `json:"officeIdentity"`
	LegacyIdentity   string `json:"office_identity"`
	OfficeOrgName    string `json:"officeOrgName"`
	LegacyOfficeName string `json:"office_org_name"`
	OfficeOrgRole    string `json:"officeOrgRole"`
	LegacyOfficeRole string `json:"office_org_role"`
}

func (in raccoonImportInput) credential() (raccoon.Credential, string, error) {
	if raw := strings.TrimSpace(in.Token); strings.HasPrefix(raw, "{") {
		var pasted raccoonImportInput
		if err := json.Unmarshal([]byte(raw), &pasted); err != nil {
			return raccoon.Credential{}, "", errors.New("auth.json 格式无效")
		}
		pasted.Name = firstNonEmpty(in.Name, pasted.Name)
		in = pasted
	}
	token := raccoon.StripBearer(firstNonEmpty(in.Token, in.AccessToken, in.LegacyAccess))
	if token == "" {
		return raccoon.Credential{}, "", errors.New("缺少 accessToken")
	}
	if strings.Count(token, ".") != 2 || strings.ContainsAny(token, " \t\r\n\"{}") || raccoon.Claims(token) == nil {
		return raccoon.Credential{}, "", errors.New("accessToken 不是有效的 JWT")
	}
	cred := raccoon.Credential{
		Token:        token,
		RefreshToken: raccoon.StripBearer(firstNonEmpty(in.RefreshToken, in.LegacyRefresh)),
		UserID:       raccoon.UserID(token),
		ExpiresAt:    raccoon.Expiry(token),
		IAM:          raccoon.IsIAM(token),
		OrgCode:      firstNonEmpty(in.OfficeIdentity, in.LegacyIdentity),
		OrgName:      firstNonEmpty(in.OfficeOrgName, in.LegacyOfficeName),
		OrgRole:      firstNonEmpty(in.OfficeOrgRole, in.LegacyOfficeRole),
	}
	if cred.IAM {
		if cred.ExpiresAt.IsZero() || raccoon.ValidateIAM(token) != nil {
			return raccoon.Credential{}, "", errors.New("小浣熊 IAM 登录态无效或已过期，请在官方客户端重新登录后再导入")
		}
		cred.RefreshToken = ""
	}
	return cred, in.Name, nil
}

// raccoonImportAccount adds an account from a pasted token (or the contents of
// the official client's auth.json). This is the path a server deployment uses
// when the browser cannot reach a loopback callback.
func (o *Operations) raccoonImportAccount(w http.ResponseWriter, r *http.Request) {
	var in raccoonImportInput
	if !decode(w, r, &in) {
		return
	}
	cred, name, err := in.credential()
	if err != nil {
		writeErr(w, http.StatusBadRequest, err.Error())
		return
	}
	// The profile is what carries the office identity; without it an
	// organisation account would silently send personal requests.
	client := raccoon.New(nil)
	ctx, cancel := context.WithTimeout(context.WithoutCancel(r.Context()), 30*time.Second)
	defer cancel()
	if profile, err := client.UserInfo(ctx, cred.Token); err == nil {
		if id := raccoon.ProfileUserID(profile); id != "" {
			cred.UserID = id
		}
		cred.OrgCode = firstNonEmpty(strOf(profile, "officeIdentity"), strOf(profile, "office_identity"), cred.OrgCode)
		cred.OrgName = firstNonEmpty(strOf(profile, "officeOrgName"), strOf(profile, "office_org_name"), cred.OrgName)
		cred.OrgRole = firstNonEmpty(strOf(profile, "officeOrgRole"), strOf(profile, "office_org_role"), cred.OrgRole)
	} else if errors.Is(err, raccoon.ErrNeedsLogin) && (cred.IAM || cred.RefreshToken == "" || !raccoon.Expired(cred.Token, time.Now())) {
		writeErr(w, http.StatusBadRequest, "小浣熊登录态已被上游拒绝，请重新登录后再导入")
		return
	}
	if cred.UserID == "" {
		writeErr(w, http.StatusBadRequest, "token 不是有效的 JWT，解析不出账号 id")
		return
	}
	rec, err := o.saveRaccoonCredential(cred, name, "raccoon-import")
	if err != nil {
		writeErr(w, raccoonLoginHTTPStatus(err), err.Error())
		return
	}
	o.afterRaccoonLogin(rec)
	writeJSON(w, http.StatusOK, map[string]any{
		"ok": true, "uid": rec.UID, "nickname": rec.Nickname, "iam": cred.IAM,
	})
}

func strOf(m map[string]any, key string) string {
	if v, ok := m[key].(string); ok {
		return v
	}
	return ""
}

// writeRaccoonPage renders the callback landing page.
func writeRaccoonPage(w http.ResponseWriter, status int, title, detail string) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Referrer-Policy", "no-referrer")
	w.WriteHeader(status)
	_, _ = w.Write([]byte("<!doctype html><meta charset=utf-8><title>" + title + "</title>" +
		"<body style=\"font-family:system-ui;padding:48px;text-align:center\"><h2>" + title +
		"</h2><p>" + html.EscapeString(detail) + "</p></body>"))
}
